#!/usr/bin/env python3
"""Build script for INJ-09-2026-W4-AECN (AECN rail weekly removal) QA checklist."""
import json
import math
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3] / "skills/qa/batch-qa-aecn/scripts"))
import openpyxl
from openpyxl.styles import Font, PatternFill, Alignment
from checklist_lib import build_with_validation

HERE = Path(__file__).parent
SOURCE_READS = HERE / "batch_INJ-09-2026-W4-AECN_source_reads.json"
OUT = HERE / "Batch_INJ-09-2026-W4-AECN_QA_Checklist.xlsx"
L = json.load(open(SOURCE_READS))

comp = L["certify"]["components"]
def cv(n):
    return comp[n]["value_t"]
def inp(n, k):
    return comp[n]["inputs"][k]
SEQ = "Injection sequestration"
PP, PE = "AECN pyrolysis (from rail loads) - process emissions", "AECN pyrolysis (from rail loads) - embodied emissions"
T_AS = "AECN to SOPOR Tanker Truck Transport Process Emissions"
R_OP = "SOPOR to Opelousas Rail Transport Process Emissions"
T_OB = "Opelousas to Basco - Tanker Truck Transport Process Emissions"
R_BR = "SOPOR to Baton Rouge Rail Process Emissions"
T_BB = "Baton Rouge to Basco Tanker Truck Process Emissions"
E_AS = "AECN to SOPOR Tanker Truck Transport Embodied Emissions"
E_R = "SOPOR to Opelousas/Baton Rouge Rail Transport Embodied Emissions"
E_TB = "Opelousas/Baton Rouge to Basco Tanker Truck Transport Embodied Emissions"
LOSS, BCU = "AECN Bio-oil Loss", "BCU - Transport Process"
PROC = [T_AS, R_OP, T_OB, R_BR, T_BB]
EMB = [E_AS, E_R, E_TB]

ops = L["ops_notes"]
roll = ops["rollup"]
cars = {r["railcar"]: r for r in ops["railcars"]}
offs = L["scale_tickets"]["offloads"]
cert = L["certify"]
EFS = L["standard_efs"]
cr = L["carbon_range"]
C = L["lab_results"]["carbon_pct"]
MOI_T = inp(SEQ, "product_mass")["value"]
M_T = inp(PP, "mass")["value"]
G = MOI_T * C / 100 * 3.667
PROC_SUM = sum(cv(n) for n in PROC)
EMB_SUM = sum(cv(n) for n in EMB)
PYRO = cv(PP) + cv(PE)
ACTS_AECN = PYRO + PROC_SUM + EMB_SUM + cv(LOSS)
Z = (C - cr["mean_C_pct"]) / cr["sd_C_pct"]
nets = [o["computed_net_lb"] for o in offs.values()]
fulls = [o["full_ticket"]["gross_weight_lb"] for o in offs.values()]
dens = [b["density_60F"] for b in L["bols"]["per_bol"].values()]
for o in offs.values():   # every empty weigh follows its full weigh
    assert (o["empty_ticket"]["date"], o["empty_ticket"]["time"]) > (o["full_ticket"]["date"], o["full_ticket"]["time"])
F = {l.split()[1]: l for l in L["recompute"]["findings"]}
gate = cert["attachment_gate"]
OPEN_DPS = list(dict.fromkeys(gate["open_datapoints"]))
loss_kg = sum(cars[c]["loss_kg"]["value"] for c in ("SHPX215053", "SHPX215039", "SHPX215091"))
inv = L["bcu_sources"]["inventory_bcu_row"]
row4 = EFS["row4_aecn_process_H2_2026"]

DERIVED = {
    "gross_calc": f"{MOI_T:.7f} t x {C / 100} x 3.667 gives {G:.6f} t; Certify {cv(SEQ):.6f} t",
    "activities_calc": f"pyrolysis {cv(PP):.6f} + {cv(PE):.6f} gives {PYRO:.6f}; process " + " + ".join(f"{cv(n):.6f}" for n in PROC) + f" gives {PROC_SUM:.6f}; embodied " + " + ".join(f"{cv(n):.6f}" for n in EMB) + f" gives {EMB_SUM:.6f}; loss {cv(LOSS):.6f}; AECN total {ACTS_AECN:.6f}; site {cert['activities_site_t']:.6f}; all {cert['activities_t']:.6f}",
    "discount_pct_calc": f"{cert['uncertainty_discount_t']:.10f} / {cv(SEQ):.6f} gives {cert['uncertainty_discount_t'] / cv(SEQ):.5f} ({cert['uncertainty_discount_t'] / cv(SEQ) * 100:.2f} %)",
    "carbon_z_calc": f"({C} - {cr['mean_C_pct']}) / {cr['sd_C_pct']} gives {Z:.3f} SD; band {cr['lower_2sd']:.2f} to {cr['upper_2sd']:.2f} %",
    "unc_calc": "14 x 72.57 gives 1,015.98 kg; 10 x 72.57 gives 725.7 kg; 4 x 72.57 gives 290.28 kg; 0.004 x 44.0 gives 0.176 %",
    "ticket_ranges_calc": f"nets {min(nets)} to {max(nets)} lb; full gross {min(fulls)} to {max(fulls)} lb",
    "loss_calc": "; ".join(f"{c} {cars[c]['loss_kg']['value']} / {cars[c]['total_loaded_kg']['value']} gives {cars[c]['loss_kg']['value'] / cars[c]['total_loaded_kg']['value'] * 100:.3f} %" for c in ("SHPX215053", "SHPX215039", "SHPX215091")) + f"; total {loss_kg:.5f} kg",
    "bol_density_range_calc": f"BOL density at 60F across 12 BOLs {min(dens)} to {max(dens)} g/mL; SGS 1.203 g/cm3 at 15C",
    "bcu_calc": f"{cv(BCU)} - {PROC_SUM:.7f} gives {cv(BCU) - PROC_SUM:.7f} t",
    "eac_calc": f"2795 - {inv['total_reduction_mt']} gives {2795 - inv['total_reduction_mt']:.4f} t; {inv['total_reduction_mt']} - {inv['used']} gives {inv['total_reduction_mt'] - inv['used']:.4f} t",
    "ticket_day_gap_calc": "2026-09-25 - 2026-09-05 gives 20 days; 2026-09-25 - 2026-09-06 gives 19 days",
}

